// Evidence is every checkable number README.md states besides the type
// counts. Each one is computed from files in the repository, so a change to
// those files makes DocCountsCheck fail until Invoke-Build DocCounts rewrites
// the block.
type Evidence struct {
	// Fields: reference/_gen/fieldmap.json (generated by tools/fieldcov).
	Fields FieldCounts
	// AccTests: func TestAcc*(t *testing.T) in internal/provider/*_test.go.
	AccTests int
	// ComposeFixtures: the cases TestAccComposeParity diffs against the
	// compose CLI: every entry of composeHashCompatFixtures plus every
	// non-swarm docker_compose block with inline content in the
	// docker_compose example (composeParityCases).
	ComposeFixtures int
	// ExampleTests: examples/**/*.tests.ps1 (Invoke-Build ExampleTests, in
	// $PreReleaseTasks).
	ExampleTests int
	// Pairwise: configs tools/pairwise -gen writes per type (deterministic,
	// fixed seed), from reference/_gen/pairwise/<type>.json.
	Pairwise map[string]int
}

// FieldCounts are the writable upstream fields by status, in total and per
// source ("engine", "compose", "bake").
type FieldCounts struct {
	Total, Mapped, Skipped, Partial, Gap int
	BySource                             map[string]*FieldCounts
}

// PairwiseTotal is the sum over every type.
func (e Evidence) PairwiseTotal() int {
	n := 0
	for _, v := range e.Pairwise {
		n += v
	}
	return n
}

// ParseFieldMap counts reference/_gen/fieldmap.json: an entry with "skip" is
// skipped, with "partial" partial, with "attr" mapped, anything else a gap.
// Entries with how "planned" (fields of unregistered Pass 7 items) are not counted.
func ParseFieldMap(b []byte) (FieldCounts, error) {
	var doc struct {
		Fields map[string]map[string]any `json:"fields"`
	}
	if err := json.Unmarshal(b, &doc); err != nil {
		return FieldCounts{}, fmt.Errorf("fieldmap: %w", err)
	}
	if len(doc.Fields) == 0 {
		return FieldCounts{}, fmt.Errorf("fieldmap: no fields")
	}
	fc := FieldCounts{BySource: map[string]*FieldCounts{}}
	for key, v := range doc.Fields {
		src, _, ok := strings.Cut(key, ":")
		if !ok {
			return FieldCounts{}, fmt.Errorf("fieldmap: key %q has no source prefix", key)
		}
		if v["how"] == "planned" {
			continue // Pass 7: a field of an unregistered planned item is not provider coverage yet
		}
		s := fc.BySource[src]
		if s == nil {
			s = &FieldCounts{}
			fc.BySource[src] = s
		}
		for _, c := range []*FieldCounts{&fc, s} {
			c.Total++
			switch {
			case v["skip"] != nil:
				c.Skipped++
			case v["partial"] != nil:
				c.Partial++
			case v["attr"] != nil:
				c.Mapped++
			default:
				c.Gap++
			}
		}
	}
	return fc, nil
}

var accFuncRe = regexp.MustCompile(`(?m)^func TestAcc\w*\(t \*testing\.T\)`)

// CountAccTests counts the TestAcc functions in the *_test.go files of dir.
func CountAccTests(dir string) (int, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*_test.go"))
	if err != nil {
		return 0, err
	}
	n := 0
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			return 0, err
		}
		n += len(accFuncRe.FindAll(b, -1))
	}
	if n == 0 {
		return 0, fmt.Errorf("acceptance tests: no func TestAcc* in %s", dir)
	}
	return n, nil
}

// CountMapLiteral returns the number of elements of the composite literal
// assigned to the package-level var name in the Go file at path.
func CountMapLiteral(path, name string) (int, error) {
	f, err := parser.ParseFile(token.NewFileSet(), path, nil, 0)
	if err != nil {
		return 0, err
	}
	for _, d := range f.Decls {
		g, ok := d.(*ast.GenDecl)
		if !ok || g.Tok != token.VAR {
			continue
		}
		for _, s := range g.Specs {
			vs := s.(*ast.ValueSpec)
			for i, id := range vs.Names {
				if id.Name != name || i >= len(vs.Values) {
					continue
				}
				cl, ok := vs.Values[i].(*ast.CompositeLit)
				if !ok {
					return 0, fmt.Errorf("%s: var %s is not a composite literal", path, name)
				}
				return len(cl.Elts), nil
			}
		}
	}
	return 0, fmt.Errorf("%s: no var %s", path, name)
}

// CountComposeExampleCases mirrors composeParityExampleCases: the
// docker_compose resource blocks of the example file whose mode is not
// "swarm" and whose content is a literal string.
func CountComposeExampleCases(path string) (int, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	f, diags := hclsyntax.ParseConfig(src, path, hcl.InitialPos)
	if diags.HasErrors() {
		return 0, fmt.Errorf("%s: %s", path, diags.Error())
	}
	n := 0
	for _, b := range f.Body.(*hclsyntax.Body).Blocks {
		if b.Type != "resource" || len(b.Labels) != 2 || b.Labels[0] != "docker_compose" {
			continue
		}
		str := func(name string) string {
			a, ok := b.Body.Attributes[name]
			if !ok {
				return ""
			}
			v, d := a.Expr.Value(nil)
			if d.HasErrors() || v.Type() != cty.String {
				return ""
			}
			return v.AsString()
		}
		if str("mode") == "swarm" || str("content") == "" {
			continue
		}
		n++
	}
	return n, nil
}

// CountFiles counts the files under root whose name ends in suffix.
func CountFiles(root, suffix string) (int, error) {
	n := 0
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() && strings.HasSuffix(d.Name(), suffix) {
			n++
		}
		return nil
	})
	if err == nil && n == 0 {
		err = fmt.Errorf("no *%s under %s", suffix, root)
	}
	return n, err
}

// pairwiseLine is the summary line tools/pairwise -gen prints per type.
var pairwiseLine = regexp.MustCompile(`(?m)^(docker_\w+): .*, (\d+) configs\s*$`)

// ParsePairwiseOutput reads the per-type config counts from the stdout of
// tools/pairwise -gen.
func ParsePairwiseOutput(out string) (map[string]int, error) {
	res := map[string]int{}
	for _, m := range pairwiseLine.FindAllStringSubmatch(out, -1) {
		var n int
		fmt.Sscan(m[2], &n)
		res[m[1]] = n
	}
	if len(res) == 0 {
		return nil, fmt.Errorf("pairwise: no \"<type>: ..., <n> configs\" line in the output of tools/pairwise -gen")
	}
	return res, nil
}

// RunPairwiseGen runs tools/pairwise -gen into a fresh directory under
// workRoot (git-ignored), counts the <type>/<nn>/main.tf configs it wrote,
// checks them against its summary lines and removes the directory.
func RunPairwiseGen(goExe, workRoot string) (map[string]int, error) {
	if err := os.MkdirAll(workRoot, 0o755); err != nil {
		return nil, err
	}
	dir, err := os.MkdirTemp(workRoot, "doccounts-pairwise-")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(dir)
	out := filepath.Join(dir, "configs")
	cmd := exec.Command(goExe, "run", "./tools/pairwise", "-gen", "-out", out)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("go run ./tools/pairwise -gen: %v: %s", err, strings.TrimSpace(stderr.String()))
	}
	counts, err := ParsePairwiseOutput(stdout.String())
	if err != nil {
		return nil, err
	}
	for t, n := range counts {
		ents, err := os.ReadDir(filepath.Join(out, t))
		if err != nil {
			return nil, err
		}
		dirs := 0
		for _, e := range ents {
			if e.IsDir() {
				if _, err := os.Stat(filepath.Join(out, t, e.Name(), "main.tf")); err == nil {
					dirs++
				}
			}
		}
		if dirs != n {
			return nil, fmt.Errorf("pairwise: %s: summary says %d configs, %d <nn>/main.tf written", t, n, dirs)
		}
	}
	return counts, nil
}

// Paths of every evidence source, relative to the repository root.
type EvidenceSources struct {
	FieldMap, AccDir, ComposeFixtureFile, ComposeFixtureVar, ComposeExample, Examples, PairwiseWork, GoExe string
	SkipPairwise                                                                                           bool
}

// DefaultSources are the repository paths the README block is computed from.
var DefaultSources = EvidenceSources{
	FieldMap:           "reference/_gen/fieldmap.json",
	AccDir:             "internal/provider",
	ComposeFixtureFile: "internal/provider/compose_hash_compat_test.go",
	ComposeFixtureVar:  "composeHashCompatFixtures",
	ComposeExample:     "examples/resources/docker_compose/resource.tf",
	Examples:           "examples",
	PairwiseWork:       "test/harness/.work",
	GoExe:              "go",
}

// CollectEvidence computes every evidence number from the repository.
func CollectEvidence(s EvidenceSources) (Evidence, error) {
	var e Evidence
	b, err := os.ReadFile(s.FieldMap)
	if err != nil {
		return e, err
	}
	if e.Fields, err = ParseFieldMap(b); err != nil {
		return e, err
	}
	if e.AccTests, err = CountAccTests(s.AccDir); err != nil {
		return e, err
	}
	fx, err := CountMapLiteral(s.ComposeFixtureFile, s.ComposeFixtureVar)
	if err != nil {
		return e, err
	}
	ex, err := CountComposeExampleCases(s.ComposeExample)
	if err != nil {
		return e, err
	}
	e.ComposeFixtures = fx + ex
	if e.ExampleTests, err = CountFiles(s.Examples, ".tests.ps1"); err != nil {
		return e, err
	}
	if !s.SkipPairwise {
		if e.Pairwise, err = RunPairwiseGen(s.GoExe, s.PairwiseWork); err != nil {
			return e, err
		}
	}
	return e, nil
}

const (
	evBeginMarker = "<!-- doccounts:evidence:begin"
	evEndMarker   = "<!-- doccounts:evidence:end -->"
	evBeginLine   = evBeginMarker + " (generated by go run ./tools/doccounts -write from the files in its Computed from column; Invoke-Build DocCountsCheck fails on drift) -->"
)

// EvidenceBlock renders the README evidence table, markers included.
func EvidenceBlock(r Registry, e Evidence) string {
	var b strings.Builder
	b.WriteString(evBeginLine + "\n")
	b.WriteString("| What | Number | Computed from | Checked by |\n")
	b.WriteString("|---|---|---|---|\n")
	total := 0
	parts := make([]string, 0, len(Kinds))
	for _, k := range Kinds {
		total += len(r[k.Key])
		parts = append(parts, fmt.Sprintf("%d %s", len(r[k.Key]), k.Plural))
	}
	fmt.Fprintf(&b, "| Registered types | %d: %s | `internal/provider/registry_gen.go` (from `reference/inventory.json`) | `RegistryCheck`, `DocCountsCheck` |\n", total, strings.Join(parts, ", "))
	f := e.Fields
	srcs := make([]string, 0, len(f.BySource))
	for s := range f.BySource {
		srcs = append(srcs, s)
	}
	sort.Strings(srcs)
	per := make([]string, 0, len(srcs))
	for _, s := range srcs {
		c := f.BySource[s]
		per = append(per, fmt.Sprintf("%s %d/%d/%d", s, c.Mapped, c.Skipped, c.Partial))
	}
	fmt.Fprintf(&b, "| Writable upstream fields (Engine API request bodies and query parameters, compose-spec, bake) | %d: %d mapped to an attribute, %d skipped with a reason, %d partial, %d gaps (mapped/skipped/partial: %s) | `reference/_gen/fieldmap.json` (`tools/fieldcov`) | `FieldCoverage` |\n",
		f.Total, f.Mapped, f.Skipped, f.Partial, f.Gap, strings.Join(per, ", "))
	fmt.Fprintf(&b, "| Acceptance tests (`func TestAcc*`) | %d | `internal/provider/*_test.go` | `TestAcc` on the dind harness |\n", e.AccTests)
	fmt.Fprintf(&b, "| Compose fixtures diffed against the real compose CLI | %d | `composeHashCompatFixtures` in `internal/provider/compose_hash_compat_test.go` + the non-swarm docker_compose blocks of `examples/resources/docker_compose/resource.tf` | `TestAccComposeParity` |\n", e.ComposeFixtures)
	fmt.Fprintf(&b, "| Examples applied, re-planned empty and destroyed | %d | `examples/**/*.tests.ps1` | `ExampleTests` |\n", e.ExampleTests)
	if e.Pairwise != nil {
		ts := make([]string, 0, len(e.Pairwise))
		for t := range e.Pairwise {
			ts = append(ts, t)
		}
		sort.Strings(ts)
		pp := make([]string, 0, len(ts))
		for _, t := range ts {
			pp = append(pp, fmt.Sprintf("%s %d", strings.TrimPrefix(t, "docker_"), e.Pairwise[t]))
		}
		fmt.Fprintf(&b, "| Pairwise configs (every value pair covered; fixed seed) | %d (%s) | `go run ./tools/pairwise -gen` over `reference/_gen/pairwise/*.json` | `PairwiseTest` |\n", e.PairwiseTotal(), strings.Join(pp, ", "))
	}
	b.WriteString(evEndMarker)
	return b.String()
}

// findBlock returns the line indexes of a begin marker (prefix) and its end
// marker (-1 if absent).
func findBlock(lines []string, begin, end string) (int, int) {
	s, e := -1, -1
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if s < 0 && strings.HasPrefix(t, begin) {
			s = i
		} else if s >= 0 && t == end {
			e = i
			break
		}
	}
	return s, e
}

// CheckEvidence reports a missing (when require), unterminated or stale
// evidence block.
func CheckEvidence(doc string, r Registry, e Evidence, require bool) []Problem {
	lines := strings.Split(strings.ReplaceAll(doc, "\r\n", "\n"), "\n")
	s, end := findBlock(lines, evBeginMarker, evEndMarker)
	switch {
	case s < 0 && require:
		return []Problem{{1, "no generated evidence block (" + evBeginMarker + " ... " + evEndMarker + "); add the two marker lines, then go run ./tools/doccounts -write"}}
	case s >= 0 && end < 0:
		return []Problem{{s + 1, "evidence block has no end marker " + evEndMarker}}
	case s >= 0:
		if got := strings.Join(lines[s:end+1], "\n"); got != EvidenceBlock(r, e) {
			return []Problem{{s + 1, "generated evidence block is stale (" + evidenceDiff(lines[s:end+1], strings.Split(EvidenceBlock(r, e), "\n")) + "); run go run ./tools/doccounts -write (Invoke-Build DocCounts)"}}
		}
	}
	return nil
}

// evidenceDiff names the first row that differs.
func evidenceDiff(got, want []string) string {
	for i := 0; i < len(got) || i < len(want); i++ {
		var g, w string
		if i < len(got) {
			g = got[i]
		}
		if i < len(want) {
			w = want[i]
		}
		if g != w {
			if w == "" {
				return "extra line " + g
			}
			return "want " + w
		}
	}
	return "?"
}

// WriteEvidence replaces the evidence block of doc; ok=false when it has none.
func WriteEvidence(doc string, r Registry, e Evidence) (string, bool) {
	crlf := strings.Contains(doc, "\r\n")
	lines := strings.Split(strings.ReplaceAll(doc, "\r\n", "\n"), "\n")
	s, end := findBlock(lines, evBeginMarker, evEndMarker)
	if s < 0 || end < 0 {
		return doc, false
	}
	out := append([]string{}, lines[:s]...)
	out = append(out, strings.Split(EvidenceBlock(r, e), "\n")...)
	out = append(out, lines[end+1:]...)
	res := strings.Join(out, "\n")
	if crlf {
		res = strings.ReplaceAll(res, "\n", "\r\n")
	}
	return res, true
}

// evidenceRange is the evidence block's line range in lines (-1, -1 if absent).
func evidenceRange(lines []string) (int, int) { return findBlock(lines, evBeginMarker, evEndMarker) }
